/**
 * Site data model = the contract between the private archive and the public pages.
 *
 * Everything in `src/content/` is GENERATED by the exporters (`scripts/export_*.py`)
 * from the archive; nothing here is edited by hand. The schemas below do two things:
 *
 *  1. describe the format (and generate the TypeScript types the pages use);
 *  2. are the PRIVACY GUARD at build time: a value outside the site rules — a year
 *     beyond the cutoff, a link outside the official portals, a file path, a personal
 *     document number — breaks `astro build` instead of going live.
 *
 * The publication rules are in AGENTS.md and came from the previous site
 * (genealogia-website), decided by Ramon on 2026-10-14 and 2026-10-26.
 */
import { defineCollection, z } from 'astro:content';
import { file } from 'astro/loaders';

// ---------------------------------------------------------------- cutoffs and portals

/** Births and every other record: 100 years. */
export const GENERAL_CUTOFF = 1925;
/** Deaths: 70 years, provided the person was born by 1925. */
export const DEATH_CUTOFF = 1955;

/** Image links are published only on official portals, and only under these paths. */
export const ACCEPTED_PORTALS: Record<string, { label: string; prefixes: string[] }> = {
  'www.familysearch.org': { label: 'FamilySearch', prefixes: ['/ark:/61903/', '/search/film/'] },
  'antenati.cultura.gov.it': { label: 'Portale Antenati', prefixes: ['/ark:/'] },
  'www.archiviodiocesanoreggiobova.it': {
    label: 'Arquivo Diocesano de Reggio Calabria–Bova',
    prefixes: ['/photo_details/', '/wp-content/uploads/wp_photo_seller/', '/consultazione-registri-parrocchiali/'],
  },
  'www.gazzettaufficiale.it': { label: 'Gazzetta Ufficiale', prefixes: ['/eli/'] },
};

// ---------------------------------------------------------------- elementary guards

/** Patterns that may never appear in a published field (the same sweep as the exporters). */
const PRIVATE = /(?:\/Users\/|\/home\/|file:\/\/|\b(?:CPF|RG)\s*[:=]|\d{3}\.\d{3}\.\d{3}-\d{2})/i;

/** Free text that goes to a page: no local paths, no personal identifiers. */
export const publicText = z.string().refine((v) => !PRIVATE.test(v), {
  message: 'field contains a local path or a personal identifier; review the row in the archive',
});

/** Image URL on an accepted official portal. */
export const portalUrl = z
  .string()
  .url()
  .refine(
    (v) => {
      try {
        const u = new URL(v);
        const portal = ACCEPTED_PORTALS[u.hostname];
        return u.protocol === 'https:' && !!portal && portal.prefixes.some((p) => u.pathname.startsWith(p));
      } catch {
        return false;
      }
    },
    { message: 'link outside the accepted official portals' },
  );

/** The archive's confidence vocabulary, as is; «rejected» is never published. */
export const Confidence = z.enum(['certain', 'stated', 'probable', 'doubtful']);
/** Reading grade of a transcribed name (archive vocabulary, visitor-facing). */
export const Reading = z.string().regex(/^(certa|provável|duvidosa)(?:$| \()/, 'reading grade not recognised');
export const Line = z.enum(['suraci', 'cardillo', 'marsicano', 'vecchia', 'rede']);

const publishableYear = z.number().int().min(1000).max(DEATH_CUTOFF);

/** An interval [start, end] respects the cutoff of its category. */
function withinCutoff(d: { start: number; end: number; category: string }): boolean {
  const limit = d.category === 'Óbitos' ? DEATH_CUTOFF : GENERAL_CUTOFF;
  return d.start <= d.end && d.end <= limit;
}

// ---------------------------------------------------------------- records seen (REAL)

/**
 * One occurrence: a name read on a register image, with the role it plays in the act.
 * Comes from `01 Indice/registros-vistos/linhas-transcritas.csv`, already filtered by the exporter.
 */
const recordNames = defineCollection({
  loader: file('src/content/records/names.json'),
  schema: z
    .object({
      id: z.string().regex(/^L-\d+$/),
      given_name: publicText.min(1),
      surname: publicText,
      father: publicText,
      mother: publicText,
      spouse_given_name: publicText,
      spouse_surname: publicText,
      comune: publicText.min(1),
      series: publicText.min(1),
      year: publicText,
      part: publicText,
      act_number: publicText,
      event_date: publicText,
      image: publicText,
      role: publicText,
      roles: z.array(publicText).min(1),
      reading: Reading,
      review: publicText,
      note: publicText,
      url: portalUrl,
      portal: publicText,
      alt_url: portalUrl.optional(),
      alt_portal: publicText.optional(),
      start: publishableYear,
      end: publishableYear,
      category: publicText,
      act_id: z.string().regex(/^(A-[a-f0-9]{16})?$/),
      pages: z.array(z.string().regex(/^P-[a-f0-9]{16}$/)),
    })
    .strict()
    .refine(withinCutoff, { message: 'occurrence beyond the publication cutoff of its category' }),
});

/**
 * One consulted page: an image opened on a portal, with the coverage of the reading.
 * Comes from `mapa-imagens.csv`. The description is structural (no names copied from the free-text field).
 */
const recordPages = defineCollection({
  loader: file('src/content/records/pages.json'),
  schema: z
    .object({
      id: z.string().regex(/^P-[a-f0-9]{16}$/),
      comune: publicText.min(1),
      series: publicText.min(1),
      year: publicText,
      part: publicText,
      image: publicText,
      collection: publicText,
      volume_or_waypoint: publicText,
      dgs_or_manifest: publicText,
      printed_pages: publicText,
      coverage: z.enum(['lida inteira', 'procurada', 'cabeçalho']),
      coverages: z.array(z.enum(['lida inteira', 'procurada', 'cabeçalho'])).min(1),
      url: portalUrl,
      portal: publicText,
      start: publishableYear,
      end: publishableYear,
      category: publicText,
      description: publicText,
      consulted_on: z.string().regex(/^(\d{4}-\d{2}-\d{2})?$/),
      visits: z.number().int().min(1),
      transcribed_names: z.number().int().min(0),
    })
    .strict()
    .refine(withinCutoff, { message: 'page beyond the publication cutoff of its category' }),
});

/** Export metadata (current cutoffs, date of the last consultation). */
const recordsMeta = defineCollection({
  loader: file('src/content/records/meta.json'),
  schema: z
    .object({
      version: z.literal(1),
      cutoffs: z.object({
        births_and_others: z.literal(GENERAL_CUTOFF),
        deaths: z.literal(DEATH_CUTOFF),
        born_by: z.literal(GENERAL_CUTOFF),
      }),
      last_consulted: z.string().regex(/^(\d{4}-\d{2}-\d{2})?$/),
      generated_on: z.string(),
      totals: z.object({ names: z.number().int(), pages: z.number().int() }),
    })
    .strict(),
});

// ---------------------------------------------------------------- persons and documents (REAL)
// Generated by scripts/export_persons_documents.py from persons.yaml and the record sheets' YAML front matter.

/** Reference to an archive document by its public id (IT-SOR-001, BR-CAR-004…). */
const documentId = z.string().regex(/^(IT|BR|UY|US|DE)-[A-Z]{3}-\d{3}[a-z]?$/);
const personId = z.string().regex(/^P-[a-z0-9]+-[a-z0-9]+(-\d{4})?$/);

/** A date as the archive writes it: ISO (full, month or year), approximate («~1736»), bound («<1810-05-08») or window («1802/1816», «/1865-09-01»). */
const archiveDate = z.string().regex(/^(?=.)[~<>]?(\d{4}(-\d{2}(-\d{2})?)?)?(\/\d{4}(-\d{2}(-\d{2})?)?)?$/, 'date outside the archive formats');

function yearOf(date: string | undefined): number | null {
  const m = (date ?? '').match(/(\d{4})/);
  return m ? Number(m[1]) : null;
}

/** A dated fact with the confidence and the basis that support it — the archive rule: no conclusion without evidence. */
const event = z
  .object({
    date: archiveDate.optional(),
    place: publicText.optional(),
    confidence: Confidence,
    basis: publicText,
    documents: z.array(documentId),
  })
  .strict();

/**
 * Edge of the evidence graph: father, mother, spouse, sibling or child, according to which acts.
 * Without a published document, only with `reference` (type, place, year of an unpublished document):
 * allowed only on the relations reaching the anchors and their parents (2026-11-07).
 */
const relation = z
  .object({
    type: z.enum(['father', 'mother', 'spouse', 'sibling', 'child']),
    person: personId,
    confidence: Confidence,
    documents: z.array(documentId),
    reference: publicText.regex(/não publicad[oa]$/, 'a reference must say the document is not published').optional(),
    rationale: publicText.optional(),
  })
  .strict()
  .refine((r) => r.documents.length > 0 || !!r.reference, { message: 'relation with no published document and no reference' });

/** What an act wrote about the person: the name as on paper, role in the act, age, occupation, literacy. */
const appearance = z
  .object({
    document: documentId,
    name_as_written: publicText.min(1),
    roles: z.array(publicText).min(1),
    age: z.number().int().min(0).max(120).optional(),
    occupation: publicText.optional(),
    literate: z.boolean().optional(),
  })
  .strict();

const persons = defineCollection({
  loader: file('src/content/persons.json'),
  schema: z
    .object({
      id: personId,
      display_name: publicText.min(1),
      aliases: z.array(publicText),
      sex: z.enum(['M', 'F', '?']),
      line: Line,
      birth: event.optional(),
      death: event.optional(),
      occupation: publicText.optional(),
      familysearch: z.string().regex(/^[A-Z0-9]{4}-[A-Z0-9]{3}$/).optional(),
      /** The `public_summary` of persons.yaml; empty while not yet written. The internal `summary` never gets here. */
      public_summary: publicText,
      /** Why the person passes the 1925 cutoff (birth, death, adult appearance, or parent of someone who passes). */
      cutoff_basis: publicText.min(1),
      /** In the graph only through a secondary source (FamilySearch tree); the site shows «carece pesquisa». */
      needs_research: z.literal(true).optional(),
      /** The couple where the lines meet: named, labelled («Meu avô»), no dossier. */
      anchor: z.object({ label: publicText.min(1) }).strict().optional(),
      no_dossier: z.literal(true).optional(),
      relations: z.array(relation),
      appearances: z.array(appearance),
    })
    .strict()
    // Nobody born after 1925 — the last barrier, after the exporter.
    .refine((p) => (yearOf(p.birth?.date) ?? 0) <= GENERAL_CUTOFF, { message: 'person born after the 1925 cutoff' }),
});

/** The archive's record_type vocabulary; the site labels each by country. */
export const DOCUMENT_TYPES = [
  'birth', 'baptism', 'marriage', 'marriage_banns', 'marriage_file', 'parish_marriage', 'death', 'burial', 'census',
  'military', 'passenger_list', 'passport', 'notarial', 'index', 'newspaper', 'other',
] as const;
const DEATH_TYPES = new Set(['death', 'burial']);

const personInDocument = appearance.omit({ document: true }).extend({ person: personId, confidence: Confidence }).strict();
const transcribedName = appearance.omit({ document: true }).strict();

const documents = defineCollection({
  loader: file('src/content/documents.json'),
  schema: z
    .object({
      id: documentId,
      title: publicText.min(1),
      type: z.enum(DOCUMENT_TYPES),
      type_raw: publicText,
      date: archiveDate,
      year: z.number().int().min(1000).max(DEATH_CUTOFF),
      place: publicText.min(1),
      country: z.enum(['IT', 'BR', 'UY', 'US', 'DE']),
      jurisdiction: publicText,
      repository: publicText.min(1),
      reference: publicText,
      /** Link to the image on an accepted official portal; absent when the document came by mail or from a registry office. */
      url: portalUrl.optional(),
      portal: publicText.optional(),
      persons: z.array(personInDocument),
      transcribed_names: z.array(transcribedName),
      /** Transcribed text only — no image is ever published (rule of 2026-10-14). Full only up to 1925. */
      transcription: publicText,
      caveats: publicText,
      lines: z.array(Line),
    })
    .strict()
    .refine((d) => d.year <= (DEATH_TYPES.has(d.type) ? DEATH_CUTOFF : GENERAL_CUTOFF), {
      message: 'document beyond the publication cutoff of its type',
    }),
});

// ---------------------------------------------------------------- next phases (CONTRACT)
// Schemas defined now to fix the format; the files are still empty ([]).

const researchFronts = defineCollection({
  loader: file('src/content/research-fronts.json'),
  schema: z
    .object({
      id: z.string().regex(/^[A-Z]\d+(\.\d+)?$/),
      line: Line,
      title: publicText.min(1),
      status: z.enum(['resolved', 'in_progress', 'waiting_for_archive', 'wall']),
      target_person: z.string().regex(/^P-[a-z0-9-]+$/).optional(),
      comune: publicText.optional(),
      hypothesis: publicText,
      findings: publicText,
      requests: z.array(
        z
          .object({
            institution: publicText.min(1),
            date: z.string().regex(/^\d{4}-\d{2}(-\d{2})?$/),
            status: z.enum(['sent', 'searching', 'document_found', 'negative_certificate', 'no_reply']),
          })
          .strict(),
      ),
      negative_searches: z.array(z.string().regex(/^NEG-\d{3}$/)),
      next_steps: publicText,
      updated_on: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    })
    .strict(),
});

const itinerary = defineCollection({
  loader: file('src/content/itinerary.json'),
  schema: z
    .object({
      id: z.string().regex(/^E-[a-z0-9-]+$/),
      line: Line,
      order: z.number().int().min(1),
      period: publicText.min(1),
      title: publicText.min(1),
      place: publicText.min(1),
      coordinates: z.object({ lat: z.number().min(-90).max(90), lon: z.number().min(-180).max(180) }).strict(),
      /** The map draws documented legs solid and the rest dashed. */
      confidence: z.enum(['documented', 'probable', 'hypothesis']),
      narrative: publicText,
      documents: z.array(documentId),
      historical_context: publicText.optional(),
    })
    .strict(),
});

export const collections = {
  recordNames,
  recordPages,
  recordsMeta,
  persons,
  documents,
  researchFronts,
  itinerary,
};
